import ajax from "@/utils/ajax";
import React, { useState, useEffect } from "react";
import { 
  Select,
  Input,
  Button,
  Spin,
  Avatar,
  Message,
  Skeleton,
  Typography 
} from "@arco-design/web-react";
import { 
  IconUser, 
  IconRobot, 
  IconSend,
  IconCode,
  IconSettings 
} from "@arco-design/web-react/icon";
import { useObserver } from "mobx-react-lite";
import Store from './store';
import MessageItem from "./message-item";

interface ChatMessage {
  content: string;
  role: 'user' | 'ai';
  timestamp: number;
  model?: string;
}


const AiChat = () => {

  return useObserver(() => {

    const [store] = useState(() => new Store());

    const { messages, setMessages, input, setInput, loading, setLoading, model, setModel, handleSend } = store;

    useEffect(() => {
      store.init();
    },[])


    if(!store.info) {
      return <Skeleton />
    }
  
    return (
      <div className="h-full flex flex-col bg-gradient-to-br from-gray-50">
        {/* 顶部导航 */}
        <div className="bg-white border-b border-gray-200  flex items-center justify-between">
          <div className="flex items-center space-x-2 shrink-0 mr-2">
            <IconCode className="text-blue-600 text-xl" />
            <Typography.Title heading={5} className="!m-0">
              AI 智能助手
            </Typography.Title>
          </div>
          <div>
            { store.info.name }
          </div>
        </div>
  
        {/* 聊天内容区域 */}
        <div ref={store.domRef} className="flex-1 overflow-y-auto p-6 space-y-6 max-w-4xl mx-auto w-full">
          {messages.map((message) => (
            <MessageItem key={message.key} store={store} message={message} />
          ))}
  
        </div>
  
        {/* 输入区域 */}
        <div className="bg-white border-t border-gray-200 p-4 shadow-lg">
          <div className="max-w-4xl mx-auto flex gap-3 items-end">
            <Input.TextArea
              value={input}
              onChange={setInput}
              placeholder="输入您的问题，Shift+Enter 换行..."
              autoSize={{ minRows: 2, maxRows: 4 }}
              onPressEnter={(e) => {
                if (!e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              className="flex-1 !rounded-xl !border-gray-300 focus:!border-blue-500"
              style={{ padding: '12px 16px' }}
            />
            <Button
              type="primary"
              shape="round"
              onClick={handleSend}
              disabled={loading}
              className="!h-11 !w-11 !rounded-xl bg-gradient-to-br from-blue-500 to-purple-500 hover:from-blue-600 hover:to-purple-600"
              icon={<IconSend className="text-lg" />}
            />
            <Button shape="round"
              type={store.isR1? 'primary' : 'default'}
              onClick={() => {
                setModel(store.isR1? 'deepseek-chat' : 'deepseek-reasoner');
              }}
            >
              深度思考
              </Button>
          </div>
        </div>
      </div>
    );
  })

};

export default AiChat;