import ajax from '@/utils/ajax';
import { Message } from '@arco-design/web-react';
import { makeObservable, action, observable, runInAction } from 'mobx';
import utils from 'utils';
import { PromptTemplateItem } from '../interface';
import axios from "axios"
import { delayedFunction, getUuid, throttleFunction } from '@/utils';
import React from 'react';

export interface ChatMessage {
    key: string;
    content: string;
    role: 'user' | 'ai';
    timestamp: number;
    model?: string;
}

class Store {
    id = utils.getAllQueryParam().id;
    @observable messages: ChatMessage[] = [];
    @observable input = '';
    @observable loading = false;
    @observable model = 'deepseek-reasoner';    // 'deepseek-chat'

    domRef = React.createRef<HTMLDivElement>();


    // 触发自动滚动
    onScroll = throttleFunction(() => {
        const dom = this.domRef.current;
        if(dom){
            if(dom.scrollHeight - (dom.scrollTop + dom.clientHeight) < 50){
                dom.scrollTop = dom.scrollHeight;   // 触底自动下滚
            }
        }
    },600)

    get isR1(){
        return this.model == 'deepseek-reasoner'
    }

    @action
    setMessages = (messages: ChatMessage[]) => {
        this.messages = messages;
    }

    @action
    setInput = (input: string) => {
        this.input = input;
    }

    @action
    setLoading = (loading: boolean) => {
        this.loading = loading;
    }

    @action
    setModel = (model: string) => {
        this.model = model;
    }

    handleSend = async () => {
        if (!this.input.trim() || this.loading) return;

        const userMessage: ChatMessage = {
            key: getUuid(),
            content: this.input.trim(),
            role: 'user',
            timestamp: Date.now(),
            model: this.model
        };

        try {
            this.setMessages([...this.messages, userMessage]);
            // this.setLoading(true);

            
            const aiMessage: ChatMessage = {
                key: getUuid(),
                content: this.input.trim(),
                role: 'ai',
                timestamp: Date.now(),
                model: this.model
            };

            this.setInput('');

            this.setMessages([...this.messages, aiMessage]);
        } catch (error) {
            Message.error('请求失败，请检查网络或稍后重试');
            console.error('API Error:', error);
        } finally {
            // this.setLoading(false);
        }
    };

    @observable info: PromptTemplateItem;

    // 初始执行
    init = () => {
        console.log('this.id', this.id)
        if(!this.id) return;
        ajax.post('/apijson/get', {
            "PromptTemplate": {
                id: this.id,
            }
        }).then((res) => {
            res.PromptTemplate.content = JSON.parse(res.PromptTemplate.content || '{}');
            runInAction(() => {
                this.info = res.PromptTemplate;
            })
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default Store;